package main
import "fmt"
type Timer struct {
  id string
  seconds int
}
func main() {
    var x int
    fmt.Scanln(&x)
    t := Timer{"ABC", x}
    reset(&t)
    fmt.Println(t)
}
func reset(p * Timer){
	p.seconds = 0
}

